let language='nl';
export function setLanguage(value){language=value;}
export function getLanguage(){return language;}
export function t(value, locale=language){
  const source=String(value);
  if(locale!=='en')return source;
  const key=source.trim();
  let result=Object.hasOwn(english,key)?english[key]:undefined;
  if(result===undefined){
    const patterns=[
      [/^(\d+) definities$/,(_,n)=>`${n} definitions`],
      [/^(\d+) items$/,(_,n)=>`${n} items`],
      [/^(\d+) meer relaties in inspecteur$/,(_,n)=>`${n} more relations in inspector`],
      [/^(\d+) entiteiten · (.+)$/,(_,n,stream)=>`${n} entities · ${stream}`],
      [/^scope (\d+) · laag (\d+)$/,(_,scope,layer)=>`scope ${scope} · layer ${layer}`],
      [/^(\d+) (punten|rijen|verwijzingen naar IFCX|uiterlijk-bindings)$/,(_,n,word)=>`${n} ${{punten:'points',rijen:'rows','verwijzingen naar IFCX':'references to IFCX','uiterlijk-bindings':'appearance bindings'}[word]}`],
      [/^punt (\d+)$/,(_,n)=>`point ${n}`],[/^rij (\d+)$/,(_,n)=>`row ${n}`],
      [/^Bij punt (\d+):$/,(_,n)=>`For point ${n}:`],
      [/^Bekijk entiteit (.+)$/,(_,n)=>`View entity ${n}`],
      [/^(Uitklappen|Inklappen): (.+)$/,(_,action,name)=>`${action==='Uitklappen'?'Expand':'Collapse'}: ${t(name,locale)}`],
      [/^Geselecteerd: (.+)$/,(_,name)=>`Selected: ${t(name,locale)}`],
      [/^([←→] )(.+)$/,(_,arrow,label)=>arrow+t(label,locale)],
      [/^(.+): offset (\d+), lengte (\d+)$/,(_,name,offset,length)=>`${name}: offset ${offset}, length ${length}`],
      [/^Voorbeelddata ontbreekt \(HTTP (\d+)\)\.$/,(_,status)=>`Example data is missing (HTTP ${status}).`],
    ];
    for(const [pattern,format]of patterns)if(pattern.test(key)){result=key.replace(pattern,format);break;}
    if(result===undefined&&key.includes(' · '))result=key.split(' · ').map(part=>t(part,locale)).join(' · ');
  }
  return result===undefined?source:source.replace(key,result);
}

const originals=new WeakMap(), attributes=new WeakMap();
export function translateTree(root){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  while(walker.nextNode()){
    const node=walker.currentNode;
    if(node.parentElement?.closest('script,style,pre,code,svg,.selection-id,.column-values,[data-no-i18n]'))continue;
    if(!originals.has(node))originals.set(node,node.nodeValue);
    node.nodeValue=t(originals.get(node));
  }
  for(const el of root.querySelectorAll('[aria-label],[title],[placeholder]')){
    if(el.closest('pre,code,[data-no-i18n]')||el.matches('svg *'))continue;
    if(!attributes.has(el))attributes.set(el,new Map(['aria-label','title','placeholder'].filter(a=>el.hasAttribute(a)).map(a=>[a,el.getAttribute(a)])));
    for(const [name,value]of attributes.get(el))el.setAttribute(name,t(value));
  }
}
